-- ============================================================================
-- HiWS — Hiswill Web Stack. The schema.
--
-- Create the database and load this file with:
--     mysql -uroot -proot -e "CREATE DATABASE IF NOT EXISTS hiws CHARACTER SET utf8mb4"
--     mysql -uroot -proot hiws < database.sql
--
-- WARNING: both tables are DROPped first, so importing this file destroys every
-- existing row. It is how the database is created from nothing, and how a
-- development copy is reset. It is not a migration and there is no runner.
--
-- The icon column holds a Font Awesome 6 name WITHOUT the style prefix, so
-- 'fa-screwdriver-wrench' renders as <i class="fa-solid fa-screwdriver-wrench">.
-- A value beginning 'fa-brands' is used as given, for brand marks.
--
-- The `bible` table is created empty: its 62,000 verses are text, not
-- schema, and live in database/bible.php. Load both with:
--     mysql -uroot -proot hiws < database.sql
--     php database/bible.php
-- ============================================================================

SET NAMES utf8mb4;

DROP TABLE IF EXISTS `bible`;
DROP TABLE IF EXISTS `tools`;
DROP TABLE IF EXISTS `projects`;

-- ----------------------------------------------------------------------------
-- projects — the cards on the home page. status = 0 hides a row without
-- deleting it, which is how a project still being built stays out of sight.
-- ----------------------------------------------------------------------------
CREATE TABLE `projects` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Untitled',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `url` tinytext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `icon` tinytext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `status` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `title` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `projects` VALUES (1,'Web Tools','A drawer of small online utilities for everyday jobs — domains, networking, security, colours, code and more. No sign-up, no cost.','tools','fa-screwdriver-wrench',1);
INSERT INTO `projects` VALUES (2,'Online Bible','Read the Bible online, anywhere, with nothing to install. Search a passage, open it by book and chapter, and read it on a clean, quiet page.','bible','fa-book-bible',1);
INSERT INTO `projects` VALUES (3,'Simple File Manager','A small web file manager: browse a folder, then upload, download, rename and delete, all from the browser. Handy when a phone is all you have.','sifm','fa-folder-tree',1);

-- ----------------------------------------------------------------------------
-- tools — every tool the tools project offers, with the explainer text that
-- sits under the form. `url` is the page name, so a row becomes /tools/<url>.
-- ----------------------------------------------------------------------------
CREATE TABLE `tools` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Untitled',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `keywords` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `url` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `icon` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'question-circle',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Uncategorized',
  `status` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `title` (`title`)
) ENGINE=InnoDB AUTO_INCREMENT=71 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `tools` VALUES ('1','DNS Lookup','Look up the DNS records of a domain name -- addresses, mail servers, name servers and more','','## What is DNS?\r\n**DNS (Domain Name System)** is a system that translates human-readable domain names (like `www.example.com`) into IP addresses (like `192.0.2.1`) that computers use to identify each other on the network. It functions like a phone book for the internet, allowing users to access websites using easy-to-remember names instead of numerical addresses.\r\n\n### Key Components of DNS:\r\n\n1. **Domain Names**: Structured hierarchically, consisting of levels separated by dots. For example, in `www.example.com`, "com" is the top-level domain (TLD), "example" is the second-level domain, and "www" is a subdomain.\r\n\n2. **DNS Records**: Information stored in DNS servers, including:\r\n\n   - **A Record**: Maps a domain to an IPv4 address.\r\n\n   - **AAAA Record**: Maps a domain to an IPv6 address.\r\n\n   - **CNAME Record**: Alias of one domain to another.\r\n\n3. **DNS Servers**: \r\n\n   - **Recursive Resolvers**: Handle the initial request from the client and query other DNS servers to find the answer.\r\n\n   - **Root Name Servers**: The top-level servers that direct queries to appropriate TLD servers.\r\n\n   - **TLD Name Servers**: Manage the next level of the domain hierarchy (e.g., `.com`, `.org`).\r\n\n   - **Authoritative Name Servers**: Provide the final answer for a specific domain.\r\n\n### How DNS Works:\r\n\n1. A user enters a domain name in their browser.\r\n\n2. The request is sent to a recursive resolver.\r\n\n3. If the resolver doesn\'t have the answer cached, it queries the root name server.\r\n\n4. The root server directs the resolver to a TLD server.\r\n\n5. The TLD server points to the authoritative name server for the domain.\r\n\n6. The authoritative name server provides the IP address, allowing the user\'s device to connect to the desired website.','dns-lookup','fa-server','Network','1');
INSERT INTO `tools` VALUES ('2','IP Address Lookup','Look up the country, city, network and time zone behind an IP address','','## What is an IP address?\r\nAn IP address (Internet Protocol address) is a unique numerical label assigned to each device connected to a computer network that uses the Internet Protocol for communication. It serves two main functions: identifying the host or network interface and providing the location of the device in the network.\r\n\nThere are two types of IP addresses:\r\n\n1. **IPv4**: This is the most commonly used format, consisting of four sets of numbers ranging from 0 to 255, separated by periods (e.g., 192.168.1.1).\r\n\n2. **IPv6**: This is a newer format designed to replace IPv4, consisting of eight groups of four hexadecimal digits, separated by colons (e.g., 2001:0db8:85a3:0000:0000:8a2e:0370:7334).\r\n','ip-lookup','fa-network-wired','Network','1');
INSERT INTO `tools` VALUES ('3','WHOIS Lookup','Look up who registered a domain name, when it was registered and when it runs out','','## What is WHOIS?\r\n **WHOIS** is a query and response protocol used to obtain information about the ownership of a domain name or an IP address. It allows users to find details such as:\r\n\n- **Domain Registrant**: The person or organization that registered the domain.\r\n\n- **Contact Information**: Email addresses, phone numbers, and mailing addresses of the registrant.\r\n\n- **Domain Status**: Information about the registration status, expiration date, and name servers.\r\n\n- **Registrar Information**: The company that manages the domain registration.\r\n\nTo perform a WHOIS lookup, you can use various online WHOIS services or command-line tools. Keep in mind that due to privacy regulations (like GDPR), some registrant information may be redacted or unavailable.','whois','fa-address-card','Network','1');
INSERT INTO `tools` VALUES ('4','Phone Lookup','Check where a phone number is from, what kind of line it is and how to write it in international form','','## What a phone number can tell you\nA phone number is not just digits. Its opening **country calling code** says which country it belongs to, and the **national number** that follows is laid out by rules each country sets: how long it is, which prefixes mean a mobile, a landline or a toll-free line, and how it is written there.\n\nThis tool reads those rules from the same public numbering plan library that telephone systems use, so it works for numbers anywhere in the world without needing to call anyone. It is a *format* check, not a directory: it cannot reveal a person\'s name or address, and no free service can.\n\nEnter a number in any reasonable form -- `+256 700 000000`, `0700 000000` or `256700000000` -- and choose the country if the number has no country code of its own.\n','phone-lookup','fa-phone','Miscellaneous','1');
INSERT INTO `tools` VALUES ('5','Word Lookup','Look up the meaning of an English word -- its part of speech, its senses and examples','','','word-lookup','fa-book','Miscellaneous','1');
INSERT INTO `tools` VALUES ('6','Currency Converter','Convert money from one currency to another quickly','','## What is currency?\r\n\n**Currency** refers to a system of money in general use within a particular country or economic context. It serves as a medium of exchange, a measure of value, and a store of value. Here are some key points about currency:\r\n\n### Types of Currency\r\n\n1. **Fiat Currency**: \r\n\n   - Government-issued money that is not backed by a physical commodity (like gold). Its value comes from the trust and stability of the issuing government (e.g., USD, EUR).\r\n\n2. **Commodity Currency**: \r\n\n   - Money that is backed by a physical commodity. Historically, currencies like gold or silver served this purpose.\r\n\n3. **Cryptocurrency**: \r\n\n   - A digital or virtual currency that uses cryptography for security and operates on decentralized networks (e.g., Bitcoin, Ethereum).\r\n\n### Functions of Currency\r\n\n1. **Medium of Exchange**: \r\n\n   - Facilitates transactions for goods and services.\r\n\n2. **Unit of Account**: \r\n\n   - Provides a standard measure of value, making it easier to compare prices.\r\n\n3. **Store of Value**: \r\n\n   - Maintains value over time, allowing individuals to save and defer consumption.\r\n\n### Currency Exchange\r\n\n- **Exchange Rate**: The rate at which one currency can be exchanged for another. It fluctuates based on market conditions.\r\n\n- **Foreign Exchange Market (Forex)**: A global marketplace for trading national currencies against one another.\r\n\n### Importance of Currency\r\n\n- **Economic Stability**: A stable currency promotes trade and investment.\r\n\n- **Inflation Control**: Central banks manage currency supply to control inflation and maintain economic stability.','currencies','fa-dollar-sign','Calculation','1');
INSERT INTO `tools` VALUES ('8','Source Code Viewer','View the HTML a server sends back for a URL, syntax highlighted','','## What is source code?\r\nThe term **source code** refers to the human-readable instructions written in a programming language that define the behavior of a computer program or software application. It serves as the foundation for building executable programs and is typically written in languages like PHP, Python, Java, C++, JavaScript, and many others.\r\n\n### Key Points About Source Code:\r\n\n1. **Human-Readable**: Source code is meant to be understood\n2. **Compilation/Interpretation**: Depending on the language, source code is either compiled (translated into machine code) or interpreted (executed directly by an interpreter).\n3. **Comments**: Programmers use comments within the code to explain the logic, making it easier for others (or themselves) to understand later.\n4. **Version Control**: Source code is often managed using version control systems (like Git), allowing multiple developers to collaborate and track changes.\n5. **Open Source**: Some projects are released as open source, meaning their source code is freely available for anyone to view, modify, and distribute.\n### Example of Simple Source Code\nHere\'s a simple example written in Python that prints "Hello, World!" to the console:\n```python\n# This is a simple Hello World program in Python\ndef hello_world():\r\n\n    print("Hello, World!")\r\n\nhello_world()\r\n\n```\r\n\n### Importance of Source Code\r\n\n- **Collaboration**: Multiple developers can work on the same project, making it easier to share and improve software.\r\n\n- **Maintenance**: Source code allows for easy updates and bug fixes.\r\n\n- **Learning**: Analyzing source code helps new programmers learn coding techniques and best practices.','source-code','fa-code','Programming','1');
INSERT INTO `tools` VALUES ('9','Hash Generator','Generate a hash of any text -- MD5, SHA1, SHA256, SHA512 and every other algorithm PHP knows','','## What is a hash?\r\nA **hash** is a function that converts an input (or "message") into a fixed-size string of bytes, typically in a way that is unique to each unique input. Hash functions are commonly used in various applications, including data integrity verification, password storage, and digital signatures.\r\n\n### Key Characteristics of Hash Functions:\r\n\n1. **Deterministic**: The same input will always produce the same hash output.\n2. **Fixed Size**: Regardless of the size of the input, the output (hash) is always of a fixed length. For example, SHA-256 produces a 256-bit (32-byte) hash.\n3. **Fast Computation**: It should be quick to compute the hash for any given input.\n4. **Preimage Resistance**: It should be infeasible to reverse the process, meaning you cannot easily retrieve the original input from its hash.\n5. **Collision Resistance**: It should be unlikely for two different inputs to produce the same hash output.\n6. **Avalanche Effect**: A small change in the input should produce a significantly different hash.\n### Common Hash Algorithms:\n- **MD5**: Produces a 128-bit hash; widely used but considered insecure for cryptographic purposes due to vulnerabilities.\n- **SHA-1**: Produces a 160-bit hash; also considered insecure due to found vulnerabilities.\n- **SHA-256**: Part of the SHA-2 family, produces a 256-bit hash, widely used for secure applications.\n- **SHA-3**: The latest member of the Secure Hash Algorithm family, offering different output sizes.\n### Applications of Hash Functions:\n1. **Data Integrity**: Ensuring that data has not been altered during transmission. Hashes can be compared to verify integrity.\n2. **Password Storage**: Storing hashed versions of passwords instead of plain text for security.\n3. **Digital Signatures**: Ensuring authenticity and integrity of messages.\n4. **Cryptographic Applications**: Used in various security protocols, including TLS/SSL.\r\n','hash','fa-fingerprint','Security','1');
INSERT INTO `tools` VALUES ('10','SSL Checker','Read a domain\'s TLS certificate -- who issued it, what it covers and when it expires','','## What is an SSL certificate?\r\n\nAn SSL (Secure Sockets Layer) certificate is a digital certificate that authenticates the identity of a website and enables an encrypted connection. Here are some key points about SSL certificates:\r\n\n### Purpose\n- **Encryption**: SSL certificates encrypt data transmitted between the user’s browser and the web server, ensuring confidentiality and tools integrity.\n- **Authentication**: They verify the identity of the website, helping to prevent attacks like phishing.\n### Types of SSL Certificates\n1. **Domain Validated (DV)**: Basic validation, confirming ownership of the domain.\n2. **Organization Validated (OV)**: Includes verification of the organization, providing more trust.\n3. **Extended Validation (EV)**: Offers the highest level of validation, displaying the organization’s name in the browser\'s address bar.\n### How to Obtain an SSL Certificate\n1. **Choose a Certificate Authority (CA)**: Select a trusted CA to purchase your SSL certificate.\n2. **Generate a CSR**: Create a Certificate Signing Request (CSR) on your server.\n3. **Submit the CSR**: Send it to your chosen CA along with the necessary documentation for validation.\n4. **Install the Certificate**: Once issued, install the SSL certificate on your web server.\n### Benefits\n- **Enhanced Security**: Protects sensitive information such as login credentials and payment details.\n- **SEO Advantage**: Search engines may rank secure sites higher.\n- **User Trust**: Users are more likely to trust websites with SSL certificates, indicated by a padlock icon in the browser.\n### Conclusion\nImplementing an SSL certificate is essential for maintaining security and trust for any website, especially those handling sensitive information.','ssl-check','fa-shield-halved','Security','1');
INSERT INTO `tools` VALUES ('18','URL Shortener','Turn a long link into a short one you can paste anywhere','','## What is a URL?\r\n\nA URL, or Uniform Resource Locator, is a specific type of Uniform Resource Identifier (URI) that provides a means to access a resource on the internet. Here are the main components and features of a URL:\r\n\n1. **Protocol**: This indicates the method used to access the resource. Common protocols include:\r\n\n   - `http://` (Hypertext Transfer Protocol)\r\n\n   - `https://` (HTTP Secure)\r\n\n   - `ftp://` (File Transfer Protocol)\r\n\n2. **Domain Name**: This is the human-readable address of the website, such as `www.example.com`. It identifies the server that hosts the resource.\r\n\n3. **Port (optional)**: This number can specify a particular port on the server. If omitted, the default ports are used (80 for HTTP and 443 for HTTPS). For example, `:8080` might be included in a URL if a non-standard port is being used.\r\n\n4. **Path**: This indicates the specific location of a resource on the server. For example, `/folder/page.html` points to a specific HTML page within a directory.\r\n\n5. **Query String (optional)**: This is used to pass parameters to the server, often seen in search queries. It starts with a `?` and can include multiple parameters separated by `&`. For example: `?search=keyword&sort=ascending`.\r\n\n6. **Fragment (optional)**: This is used to navigate to a specific part of a webpage and starts with a `#`. For example, `#section1` would take the user to a specific section of the page.\r\n\n### Example of a URL\r\n\n```\r\n\nhttps://www.example.com:443/folder/page.html?search=keyword#section1\r\n\n```\r\n\nIn this example:\r\n\n- **Protocol**: `https`\r\n\n- **Domain Name**: `www.example.com`\r\n\n- **Port**: `443` (optional and often omitted)\r\n\n- **Path**: `/folder/page.html`\r\n\n- **Query String**: `?search=keyword`\r\n\n- **Fragment**: `#section1` \r\n\nURLs are essential for navigating the web, as they provide the addresses needed to locate resources.\r\n\n### Note\r\n\nURLs shortened here expire in 30 days. However, each visit extends the URL expiration by another 30 days!','short-url','fa-link','Programming','1');
INSERT INTO `tools` VALUES ('20','HEX to RGB Converter','Turn a hex colour like #7C3AED into the red, green and blue values behind it','','### About HEX and RGB\r\n**HEX** and **RGB** are both ways to represent colors, but they use different systems.\r\n\n**HEX** uses six hexadecimal digits (0-9 and A-F) to represent the intensity of red, green, and blue in a color. #FF0000 represents full red (FF), no green (00), and no blue (00).\r\n\n**RGB** uses three decimal numbers (0-255) to represent the intensity of red, green, and blue. 255 is the highest intensity, while 0 is the lowest. So (255, 0, 0) means full red, no green, and no blue.\r\n\n#### HEX:\r\n\n- Uses six hexadecimal digits (0-9 and A-F).\r\n\n- Each pair of digits represents the intensity of red, green, and blue (e.g., #FF0000 is full red, no green, no blue).\r\n\n- Compact representation, often used in web development.\r\n\n#### RGB:\r\n\n- Uses three decimal numbers (0-255).\r\n\n- Each number represents the intensity of red, green, and blue (e.g., (255, 0, 0) is full red, no green, no blue).\r\n\n- More intuitive for some users, as it uses a familiar decimal system.','hex-to-rgb','fa-palette','Conversion','1');
INSERT INTO `tools` VALUES ('21','RGB to HEX Converter','Turn red, green and blue values into the hex colour a stylesheet wants','','\r\n### About HEX and RGB\r\n**HEX** and **RGB** are both ways to represent colors, but they use different systems.\r\n\r\n**HEX** uses six hexadecimal digits (0-9 and A-F) to represent the intensity of red, green, and blue in a color. #FF0000 represents full red (FF), no green (00), and no blue (00).\r\n**RGB** uses three decimal numbers (0-255) to represent the intensity of red, green, and blue. 255 is the highest intensity, while 0 is the lowest. So (255, 0, 0) means full red, no green, and no blue.\r\n\r\n#### HEX:\r\n- Uses six hexadecimal digits (0-9 and A-F).\r\n- Each pair of digits represents the intensity of red, green, and blue (e.g., #FF0000 is full red, no green, no blue).\r\n- Compact representation, often used in web development.\r\n\r\n#### RGB:\r\n- Uses three decimal numbers (0-255).\r\n- Each number represents the intensity of red, green, and blue (e.g., (255, 0, 0) is full red, no green, no blue).\r\n- More intuitive for some users, as it uses a familiar decimal system.\r\n\r\n','rgb-to-hex','fa-swatchbook','Conversion','1');
INSERT INTO `tools` VALUES ('22','Code to Text ratio','Work out how much of a page\'s weight is text and how much is code','','## What is code to text ratio?\r\n\nThe **code to text ratio** is a measure of how much of a webpage\'s source code is dedicated to displaying actual text content versus other elements like HTML tags, scripts, and styling.\r\n\n### Why a Good Code to Text Ratio Matters\r\n\nA good code to text ratio is important for several reasons:\r\n\n- **SEO:** Search engines like Google prioritize pages with valuable text content. A higher ratio often indicates more relevant and engaging content, which can boost your search rankings.\r\n\n- **User Experience:** Pages with a good ratio are typically faster to load and easier to navigate. This improves the overall user experience, making your website more enjoyable to visit.\r\n\n- **Accessibility:** A well-balanced ratio can make your website more accessible to users with disabilities, as it reduces the amount of code that screen readers need to process.\r\n\n### The Ideal Code to Text Ratio\nThe ideal ratio is generally considered to be between 25% and 70%. This means that 25% to 70% of the page should be actual text content, while the rest can be the underlying code.\r\n\n### How to Improve Your Code to Text Ratio\r\n\n- **Reduce Unnecessary Code:** Simplify your HTML by removing unnecessary tags, attributes, and comments.\r\n\n- **Optimize Images:** Use compressed images and ensure they are relevant to the content. Large images can significantly increase your code size.\r\n\n- **Increase Text Content:** Add more valuable text to your pages. This could be through blog posts, articles, or even just expanding on existing content.\r\n\n- **Avoid Excessive Styling:** While CSS is essential, avoid over-using it. Keep your stylesheets clean and efficient.','code-text-ratio','fa-percent','SEO','1');
INSERT INTO `tools` VALUES ('23','SSL Generator','Generate a self-signed certificate for a hostname, ready to paste into a server config','','## What is a self-signed SSL certificate?\r\n\nA **self-signed SSL certificate** is a type of digital certificate that is signed by the entity that created it rather than a trusted certificate authority (CA). Here are some key points about self-signed certificates:\r\n\n### Key Features:\r\n\n1. **Purpose**:\r\n\n   - Self-signed certificates are used to secure communications over the internet, typically for internal use or testing purposes.\r\n\n2. **Creation**:\r\n\n   - They can be generated easily using tools like OpenSSL without the need for a third-party CA.\r\n\n3. **Trust**:\r\n\n   - Browsers and other clients do not trust self-signed certificates by default because they are not issued by a recognized authority. This means users may see warnings when visiting a site that uses a self-signed certificate.\r\n\n4. **Cost**:\r\n\n   - Self-signed certificates are free to create, as there are no fees associated with acquiring them from a CA.\r\n\n5. **Use Cases**:\r\n\n   - Commonly used in development environments, testing, internal networks, or for encrypting communications in applications where trust is managed internally.\r\n\n6. **Limitations**:\r\n\n   - Since they are not trusted by default, they are not suitable for production environments where security and user trust are critical. Users may need to manually accept the certificate to proceed.\r\n\n### Summary:\r\n\nWhile self-signed SSL certificates can provide encryption, they do not offer the same level of trust and validation that certificates from recognized CAs do. For public-facing websites, it’s generally recommended to obtain a certificate from a trusted CA to ensure security and user confidence.','ssl-generator','fa-certificate','Security','1');
INSERT INTO `tools` VALUES ('30','Website Screenshot Generator','Capture a screenshot of a web page as it looks right now','','## Why a screenshot?\nA screenshot is the quickest way to show somebody what a page looks like without asking them to open it. It is handy for previewing a site you are building, for keeping a record of a page that may change, or for checking how a site renders on a viewport other than your own.\n\nThe picture is drawn on demand by a rendering service and handed straight back to your browser, so nothing is stored on this server. A page that is behind a login, or one that leans on heavy JavaScript, may come out incomplete -- that is a limit of the service, not of your link.\n','website-screenshot','fa-camera','Miscellaneous','1');
INSERT INTO `tools` VALUES ('31','HTTP Headers Viewer','See the HTTP headers a server answers with for a URL','','## What are HTTP Headers?\r\nHTTP headers are key-value pairs sent in HTTP requests and responses that provide essential information about the request or the response. They play a crucial role in communication between clients (like web browsers) and servers. Here\'s a breakdown of some key aspects:\r\n\n### Types of HTTP Headers\r\n\n1. **Request Headers**: Sent by the client to provide information about the request.\r\n\n   - **Examples**:\r\n\n     - `Accept`: Specifies the media types that are acceptable for the response.\r\n\n     - `User-Agent`: Contains information about the user agent (browser or client) making the request.\r\n\n     - `Authorization`: Contains credentials for authenticating the client with the server.\r\n\n2. **Response Headers**: Sent by the server to provide information about the response.\r\n\n   - **Examples**:\r\n\n     - `Content-Type`: Indicates the media type of the resource being sent.\r\n\n     - `Set-Cookie`: Used to send cookies from the server to the client.\r\n\n     - `Cache-Control`: Directives for caching mechanisms in both requests and responses.\r\n\n3. **General Headers**: Can be used in both requests and responses but do not relate to the content.\r\n\n   - **Examples**:\r\n\n     - `Date`: Represents the date and time at which the message was sent.\r\n\n     - `Connection`: Control options for the current connection.\r\n\n### Importance of HTTP Headers\r\n\n- **Control Data Transfer**: Headers can control how data is sent and received, determine caching behavior, and set content types.\r\n\n- **Authentication and Security**: Headers are often used for authentication, such as tokens and session management.\r\n\n- **Content Negotiation**: They help in determining the format of the response based on client capabilities.\r\n\n### Example of HTTP Request and Response\r\n\n**Sample HTTP Request:**\r\n\n```\r\n\nGET /index.html HTTP/1.1\r\n\nHost: www.example.com\r\n\nUser-Agent: Mozilla/5.0\r\n\nAccept: text/html\r\n\n```\r\n\n**Sample HTTP Response:**\r\n\n```\r\n\nHTTP/1.1 200 OK\r\n\nContent-Type: text/html; charset=UTF-8\r\n\nContent-Length: 1234\r\n\nDate: Sat, 12 Jan 2025 12:00:00 GMT\r\n\n<html>\r\n\n  <body>\r\n\n    <h1>Hello, World!</h1>\r\n\n  </body>\r\n\n</html>\r\n\n```\r\n\nIn summary, HTTP headers are vital for controlling the behavior of HTTP requests and responses, providing necessary context and instructions for both clients and servers.','http-headers','fa-table-list','Programming','1');
INSERT INTO `tools` VALUES ('32','ROT13,18,47 Encoding and Decoding','Encode/Decode text in ROT13,18 and 47','','## What is ROT13, ROT18 or ROT47?\r\n\n### ROT13\r\n\n- **Definition**: ROT13 is a simple letter substitution cipher that replaces each letter with the letter 13 positions later in the alphabet. It wraps around such that after \'Z\', it continues from \'A\'.\r\n\n- **How It Works**: \r\n\n  - For example:\r\n\n    - A ↔ N\r\n\n    - B ↔ O\r\n\n    - C ↔ P\r\n\n    - ...\r\n\n    - M ↔ Z\r\n\n- **Common Uses**: \r\n\n  - Often used in online forums to obscure spoilers or sensitive information.\r\n\n  - Easy to implement and symmetric, meaning encoding and decoding are the same operation.\r\n\n### ROT18\r\n\n- **Definition**: ROT18 extends the concept of ROT13 by shifting letters by 18 positions in the alphabet and digits by 8 positions (0-9).\r\n\n- **How It Works**: \r\n\n  - For letters:\r\n\n    - A ↔ S\r\n\n    - B ↔ T\r\n\n    - ...\r\n\n    - I ↔ W\r\n\n  - For digits:\r\n\n    - 0 ↔ 8\r\n\n    - 1 ↔ 9\r\n\n    - 2 ↔ 0\r\n\n    - ...\r\n\n- **Common Uses**: \r\n\n  - Less common than ROT13 but can be used to obscure text while providing a different level of obfuscation.\r\n\n### ROT47\r\n\n- **Definition**: ROT47 shifts printable ASCII characters (from 32 to 126) by 47 positions. This includes letters, digits, and various symbols.\r\n\n- **How It Works**: \r\n\n  - For example, if you apply ROT47 to the character `!`, which has an ASCII value of 33, it shifts to ASCII value 80, resulting in the character `P`.\r\n\n  - The rotation wraps around after reaching the maximum printable ASCII character.\r\n\n- **Common Uses**: \r\n\n  - Used in some programming languages and applications to obscure text or code snippets.\r\n\n  - Provides a way to encode all printable characters, making it more versatile than just shifting alphabetic characters.\r\n\n> Each of these rotation algorithms provides a different method of encoding text, with varying levels of complexity and application.','rot','fa-right-left','Programming','1');

-- ----------------------------------------------------------------------------
-- tools, second set. Same shape as the rows above: the icon is a bare Font
-- Awesome name and the category groups the tool on /tools. Network and SEO are
-- older groups that simply grew; Text, Time and Generator are new. The explainer
-- (info) opens with a heading, which becomes the summary the page folds away.
-- ----------------------------------------------------------------------------
INSERT INTO `tools` VALUES ('33','What Is My IP','See the address this site sees you at, with the network details behind it','what is my ip, my ip address, find my ip','### About your IP address\nThe address shown here is the one this server sees when your browser asks for a page. Every connection you make hands it over, so there is nothing to install or type. A VPN, a proxy or a mobile network will put a different address in front of you than your home line does.\n','what-is-my-ip','fa-globe','Network','1');
INSERT INTO `tools` VALUES ('34','Reverse DNS Lookup','Find the hostname behind an IP address -- the reverse of an ordinary DNS lookup','reverse dns, ptr lookup, rdns, reverse ip','### What is reverse DNS?\nA normal lookup turns a name into an address. Reverse DNS goes the other way: it asks which name the network gave an address, using a PTR record. It is mostly housekeeping -- mail servers check it to decide whether to trust a sender -- so not every address has one.\n','reverse-dns','fa-retweet','Network','1');
INSERT INTO `tools` VALUES ('35','IPv4 Subnet Calculator','Work out the network, broadcast, mask and host range a CIDR block describes','subnet calculator, cidr, netmask, ipv4, network address','### What is a subnet?\nAn address is split into a network part and a host part by its mask. Writing the mask as a number of bits -- /24, /16 -- is called CIDR, and it is shorthand for the size of one network block. This tool takes an address and a prefix and prints the boundaries every router cares about.\n','subnet-calculator','fa-sitemap','Network','1');
INSERT INTO `tools` VALUES ('36','Email Checker','Check the shape of an email address and whether its domain can receive mail','email checker, email validator, mx record, verify email','### What this checks\nIt looks at two separate things. First the shape of the address, which is a syntax rule; then the domain after the at-sign, which is asked for the mail servers (MX records) that would accept a message. It cannot say whether a particular mailbox exists -- only the mail server itself could, and it will not.\n','email-checker','fa-envelope-circle-check','Network','1');
INSERT INTO `tools` VALUES ('37','HTTP Status Checker','Ask a URL what it answers with -- its status code, redirects and server','http status, status code, check website, http response, redirect','### What an HTTP status is\nEvery answer a web server gives starts with a three-digit code: 200 for a good page, 301 for a permanent move, 404 for a page that is not there, 500 for a server that fell over. This tool asks for a page and reports the code and the headers that came with it.\n','http-status','fa-signal','Network','1');
INSERT INTO `tools` VALUES ('38','Port Checker','See whether a host has a particular network port open and answering','port check, open port, port scanner, tcp port','### What a port check does\nA server offers services on numbered ports -- 80 for the web, 443 for secure web, 22 for SSH. This tool opens a single connection to a host and port and reports whether anything accepted it, within a short timeout. It checks one door; it does not scan a range.\n','port-check','fa-plug','Network','1');
INSERT INTO `tools` VALUES ('39','Base64 Encoder & Decoder','Turn text into Base64, or read Base64 back into the text it stands for','base64, encode, decode, base64 converter','### What is Base64?\nBase64 rewrites bytes using sixty-four printable characters, so data that a text channel cannot carry -- an image inside a stylesheet, a token in a URL -- survives the trip. It hides nothing: anyone can turn it back, so it is an encoding, never encryption.\n','base64','fa-keyboard','Programming','1');
INSERT INTO `tools` VALUES ('40','URL Encoder & Decoder','Escape text so it can sit safely in a URL, or read it back again','url encode, url decode, percent encoding, url encoding','### What is URL encoding?\nA URL may only contain a limited set of characters, so anything outside it -- a space, an ampersand, a non-Latin letter -- is written as a percent sign and two hex digits. This tool applies that rule, and undoes it.\n','url-encode','fa-anchor','Programming','1');
INSERT INTO `tools` VALUES ('41','HTML Entity Encoder & Decoder','Turn characters such as a less-than sign into HTML entities, and back','html encode, html decode, html entities, escape html','### What is an HTML entity?\nCharacters that would otherwise be read as markup -- a less-than sign, an ampersand -- are written as named or numeric entities. Encoding text this way lets it be shown as written inside a page. Decoding turns those entities back into the characters themselves.\n','html-entities','fa-file-lines','Programming','1');
INSERT INTO `tools` VALUES ('42','JSON Formatter','Validate JSON and print it neatly indented, ready to read','json formatter, json validator, prettify json, json beautifier','### What is JSON?\nJSON is a plain-text way of writing structured data -- objects of key and value, lists, numbers, strings -- that machines and people can both read. This tool parses what you paste, reports any error together with the point it happened at, and prints the result indented.\n','json-format','fa-file-code','Programming','1');
INSERT INTO `tools` VALUES ('43','Markdown to HTML','Convert Markdown text into HTML you can paste into a page','markdown, markdown to html, md converter','### What is Markdown?\nMarkdown is a light way of writing formatted text: hashes for headings, asterisks for emphasis, dashes for lists. It is meant to be readable as written. This tool runs it through a parser and hands back the HTML that the same text stands for.\n','markdown','fa-brands fa-markdown','Programming','1');
INSERT INTO `tools` VALUES ('44','CSS Minifier','Strip the comments and needless whitespace out of a stylesheet','css minifier, minify css, compress css','### What minifying does\nA stylesheet is written for people, with indentation and comments. A browser needs none of that, so minifying removes comments, collapses whitespace and drops the last semicolon in a block. The page looks the same; the file is smaller.\n','css-minifier','fa-paint-roller','Programming','1');
INSERT INTO `tools` VALUES ('45','HTML Minifier','Collapse the whitespace and comments in a block of HTML','html minifier, minify html, compress html','### What minifying does\nHTML is mostly whitespace and markup a browser does not need. Minifying removes comments and collapses runs of spaces, tabs and blank lines, which trims the page\'s weight. It is a tidy-up, not a rewrite, so the markup itself is left alone.\n','html-minifier','fa-compress','Programming','1');
INSERT INTO `tools` VALUES ('46','Password Generator','Create a strong random password of the length and shape you choose','password generator, strong password, random password','### What makes a password strong\nLength and unpredictability matter more than symbols. This tool draws characters from the system\'s cryptographic random source, not from a predictable sequence, so the result cannot be guessed from the other passwords it has handed out.\n','password-generator','fa-key','Security','1');
INSERT INTO `tools` VALUES ('47','Password Strength Checker','Estimate how long a password would take to crack by guessing','password strength, password checker, how strong is my password','### How strength is judged\nLength is the single biggest factor. This tool counts the character set a password draws on, works out the number of possible combinations, and turns that into a guessing time. It is a guide, not a verdict: a password that is long but is a known phrase is weaker than it looks.\n','password-strength','fa-shield','Security','1');
INSERT INTO `tools` VALUES ('48','.htpasswd Generator','Create an Apache password entry to put a folder behind a login','htpasswd, apache password, basic auth, htaccess password','### What .htpasswd is\nApache can ask for a username and password before it serves a directory. The passwords live in a file called .htpasswd, one line per user, stored as a hash. This tool writes that line for you; paste it into the file and point .htaccess at it.\n','htpasswd','fa-user-lock','Security','1');
INSERT INTO `tools` VALUES ('49','Number Base Converter','Convert a number between binary, octal, decimal and hexadecimal','number base, binary to decimal, hex converter, radix','### What a number base is\nWe count in tens because we have ten fingers, but a computer counts in twos. The same quantity can be written in any base: 255 in decimal is 11111111 in binary and FF in hexadecimal. This tool translates one into the others.\n','number-base','fa-hashtag','Conversion','1');
INSERT INTO `tools` VALUES ('50','Unit Converter','Convert between common units of length, mass, temperature and more','unit converter, length, weight, temperature, measurement','### About units\nDifferent countries and trades measure the same thing in different units -- metres and feet, kilograms and pounds. A conversion is a fixed multiplication, except for temperature, which is a shift and a scale rather than a simple ratio. This tool handles both kinds.\n','unit-converter','fa-ruler-combined','Conversion','1');
INSERT INTO `tools` VALUES ('51','Text & Binary Converter','Turn text into the binary that stores it, and binary back into text','text to binary, binary to text, binary converter','### About binary text\nEvery character a computer stores is a number, and every number can be written in base two. Converting text to binary writes those numbers out as eight-bit groups. The conversion depends on the character encoding -- here, UTF-8.\n','binary','fa-microchip','Conversion','1');
INSERT INTO `tools` VALUES ('52','Roman Numeral Converter','Convert between Roman numerals and ordinary numbers','roman numerals, roman numeral converter, numeral','### About Roman numerals\nRoman numerals build a number from letters -- I, V, X, L, C, D, M -- added together, with a smaller letter before a larger one meaning subtraction, as in IV for four. The system has no zero and no place value, so it cannot express very large numbers cleanly.\n','roman','fa-v','Conversion','1');
INSERT INTO `tools` VALUES ('53','Meta Tag Generator','Write the title, description and social tags a page should carry','meta tags, meta tag generator, seo, open graph','### What meta tags do\nA meta tag describes a page to machines: the title a search result shows, the summary beneath it, the card a link unfurls into on social media. Search engines may rewrite them, but a clear, honest description is still what earns the click.\n','meta-tags','fa-tags','SEO','1');
INSERT INTO `tools` VALUES ('54','Robots.txt Generator','Build a robots.txt that tells crawlers what to index and where the sitemap is','robots.txt, robots generator, crawl rules, seo','### What robots.txt is\nA file at the root of a site that tells visiting crawlers which parts they may fetch. It is a request, not a wall: a well-behaved crawler obeys it, and a determined one ignores it. It is the polite way to point a search engine at your sitemap and away from private paths.\n','robots','fa-robot','SEO','1');
INSERT INTO `tools` VALUES ('55','Keyword Density Checker','See which words a block of text repeats, and how often','keyword density, word frequency, seo, keyword analysis','### What keyword density is\nThe share of a piece of writing that one word or phrase makes up. It is a rough signal at best -- search engines long ago stopped rewarding stuffing -- but counting is still a quick way to see what a page is actually about, and whether it drifts.\n','keyword-density','fa-magnifying-glass-chart','SEO','1');
INSERT INTO `tools` VALUES ('56','Slug Generator','Turn a title into a clean, URL-safe address segment','slug generator, url slug, permalink, seo url','### What a slug is\nThe readable part of an address that stands for a page\'s title -- this-page rather than a number. A good slug is lowercase, uses hyphens between words and drops punctuation, which keeps the address easy to read and to share.\n','slug','fa-tag','SEO','1');
INSERT INTO `tools` VALUES ('57','Reading Time Calculator','Estimate how long a piece of writing takes to read aloud or silently','reading time, word count, reading speed, blog','### About reading time\nIt is a rough guess: the number of words divided by an average reading speed. People read at very different rates, and technical text is slower than a novel. Used honestly -- as a label, not a promise -- it tells a visitor whether a piece fits the next five minutes.\n','reading-time','fa-stopwatch','SEO','1');
INSERT INTO `tools` VALUES ('58','Percentage Calculator','Work out percentages, increases, decreases and shares of a number','percentage calculator, percent, percent change','### About percentages\nA percentage is a fraction written out of a hundred, which makes two different quantities easy to compare. Most everyday problems are one of three shapes -- what is this percent of a number, what percent is one number of another, and how much has it changed -- and this tool answers each.\n','percentage','fa-divide','Calculation','1');
INSERT INTO `tools` VALUES ('59','BMI Calculator','Work out body mass index from a height and a weight','bmi, body mass index, bmi calculator, health','### What BMI is\nBody mass index is a weight divided by a height squared, giving a single number that places an adult in a broad band. It is a rough public-health measure: it ignores muscle, frame and age, so treat it as one clue among several and not a diagnosis.\n','bmi','fa-weight-scale','Calculation','1');
INSERT INTO `tools` VALUES ('60','Word & Character Counter','Count the words, characters, sentences and paragraphs in your text','word counter, character counter, count words','### About counting words\nMost places count a word as a run of characters between spaces, which is simple and usually close enough. It can trip over punctuation and hyphenation, so treat the number as a good estimate. Characters are counted both with and without spaces, because forms often ask for one or the other.\n','word-counter','fa-spell-check','Text','1');
INSERT INTO `tools` VALUES ('61','Case Converter','Change the case of text -- upper, lower, title, sentence and more','case converter, uppercase, lowercase, title case','### About letter case\nChanging case is a small tidy-up that editors and writers reach for constantly: a shouted heading to lower it, a title written correctly, SHOUTING turned down. Each style has its own rule for which words are capitalised, and this tool applies them.\n','case-converter','fa-font','Text','1');
INSERT INTO `tools` VALUES ('62','Remove Line Breaks','Turn a block of wrapped text into one line, or into neat paragraphs','remove line breaks, join lines, unwrap text','### Why line breaks need removing\nText copied out of an email, a PDF or a terminal often carries a line break at the end of every visual line, which is not where the sentence ends. This tool joins those lines back into flowing text, with a choice of how paragraphs should be marked.\n','remove-line-breaks','fa-text-slash','Text','1');
INSERT INTO `tools` VALUES ('63','Lorem Ipsum Generator','Generate placeholder Latin text in the amount and shape you need','lorem ipsum, placeholder text, dummy text','### About Lorem Ipsum\nIt is scrambled Latin, in use since the sixteenth century, that fills a layout so a designer can judge it without being distracted by the words. It is meaningless on purpose -- that is the point.\n','lorem-ipsum','fa-paragraph','Text','1');
INSERT INTO `tools` VALUES ('64','Reverse Text','Reverse text by character, by word or by line','reverse text, backwards text, flip text','### About reversing text\nReversing by character turns a word back to front; reversing by word or line keeps each one whole but changes the order. All three are handy for puzzles, and for checking a value against its mirror.\n','reverse-text','fa-shuffle','Text','1');
INSERT INTO `tools` VALUES ('65','Sort & Remove Duplicate Lines','Sort a list of lines and drop the duplicates in one pass','sort lines, remove duplicates, dedupe list, alphabetical sort','### About tidying lists\nPasting a list of names, links or codes often leaves it out of order and full of repeats. Sorting puts it in a known order; removing duplicates leaves one of each. This tool does both, so a list can be cleaned in a single step.\n','sort-lines','fa-arrow-down-a-z','Text','1');
INSERT INTO `tools` VALUES ('66','Timestamp Converter','Convert between a Unix timestamp and a readable date and time','timestamp converter, unix time, epoch converter, unix timestamp','### What a Unix timestamp is\nA single number: the seconds counted from the first of January 1970 in UTC. Computers prefer it to a written date because it is one value, has no time zone, and sorts in order. This tool turns it into a readable date, and a date back into it.\n','timestamp','fa-clock','Time','1');
INSERT INTO `tools` VALUES ('67','Age Calculator','Work out an age in years, months and days from a date of birth','age calculator, how old am i, date of birth, birthday','### About age\nThe exact age is not simply a subtraction of years: months differ in length and a leap day shifts things by one. This tool counts the whole years, the leftover months and the leftover days, so the answer reads the way a person would give it.\n','age','fa-cake-candles','Time','1');
INSERT INTO `tools` VALUES ('68','Date Difference Calculator','Count the days, weeks and months between two dates','date difference, days between dates, date calculator','### About the gap between dates\nTwo dates can be a different number of days apart depending on how the months fall, so counting by hand is easy to get wrong. This tool counts the exact days between them, and also adds the count in weeks and in years, months and days.\n','date-diff','fa-calendar-days','Time','1');
INSERT INTO `tools` VALUES ('69','UUID Generator','Generate random UUIDs -- one or many -- to use as identifiers','uuid generator, guid, unique id, uuid v4','### What a UUID is\nA 128-bit identifier written as five groups of hex digits, used where a name has to be unique without anyone keeping a list. Version 4 is random: this tool draws its bits from the system\'s cryptographic source, so two runs will not collide.\n','uuid','fa-id-badge','Generator','1');
INSERT INTO `tools` VALUES ('70','Random Number Generator','Draw random numbers in a range, with or without repeats','random number, rng, random picker, lottery numbers','### About random numbers\nA good random number is unpredictable, not merely varied. This tool draws from the system\'s cryptographic source rather than a seeded sequence, so the values are suitable for anything short of cryptography itself -- draws, lotteries, test data.\n','random-number','fa-dice','Generator','1');

-- ----------------------------------------------------------------------------
-- bible -- one row per verse, per translation. `number` is the book's place in
-- the canon (1..66) and is what a passage is looked up by, so both translations
-- line up even where their versification differs. `version` is a key in
-- BIBLE_VERSIONS (app/config.php).
--
-- Left empty on purpose -- see the note at the top of this file.
-- ----------------------------------------------------------------------------
CREATE TABLE `bible` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `version` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `number` tinyint UNSIGNED NOT NULL,
  `book` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `chapter` smallint UNSIGNED NOT NULL,
  `verse` smallint UNSIGNED NOT NULL,
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `place` (`version`,`number`,`chapter`,`verse`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
